<script setup lang="ts">
import {ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../../stores/auth'
const username=ref(''),password=ref(''),loading=ref(false),error=ref(''),auth=useAuthStore(),router=useRouter(),route=useRoute()
async function submit(){error.value='';if(!username.value.trim()||!password.value){error.value='请输入用户名和密码';return}loading.value=true;try{await auth.login(username.value.trim(),password.value);await router.replace(String(route.query.redirect||'/dashboard'))}catch(e:any){error.value=e.response?.data?.detail||e.response?.data?.non_field_errors?.[0]||'登录失败，请检查账号信息'}finally{loading.value=false}}
</script>
<template><main class="auth-page"><section class="auth-intro"><div class="brand light"><div class="brand-mark" aria-hidden="true"><span/><span/></div><div class="brand-copy"><strong>慧医云</strong><small>临床协作与运营平台</small></div></div><div class="auth-copy"><p>让数据跟上诊疗的节奏</p><h1>让每一次诊疗，<br><em>更清晰、更安心。</em></h1><span>连接患者、医师与医院运营，让预约、诊疗、检查、药房和结算在同一条可追溯的业务链路中协同。</span></div><div class="auth-proof"><b>三端协同</b><b>临床流程可追溯</b><b>智能服务可扩展</b></div></section><section class="auth-panel"><div class="auth-card"><div class="live-label"><i/>身份认证</div><h2>登录智慧医疗平台</h2><p class="muted">使用管理员、医师或患者账户继续</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="用户名"><el-input v-model="username" size="large" autocomplete="username" placeholder="请输入用户名"/></el-form-item><el-form-item label="密码"><el-input v-model="password" size="large" type="password" show-password autocomplete="current-password" placeholder="请输入密码" @keyup.enter="submit"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-button class="submit" type="primary" size="large" :loading="loading" @click="submit">安全登录</el-button></el-form><p class="auth-link">还没有患者账户？<router-link to="/register">立即注册</router-link></p></div><footer>教学演示系统 · 请勿录入真实患者隐私数据</footer></section></main></template>
